create or replace function pricing.preview_sales_working_state_pricing(
  p_tenant_id uuid,
  p_store_id uuid,
  p_customer_id uuid,
  p_currency_code text,
  p_context_version integer,
  p_effective_at timestamptz,
  p_lines jsonb
)
returns jsonb
language plpgsql
stable
security definer
set search_path = pricing, iam, partner, catalog, extensions, pg_temp
as $$
declare
  v_actor_id uuid := auth.uid();
  v_currency_code text := upper(btrim(coalesce(p_currency_code, '')));
  v_customer jsonb;
  v_customer_valid boolean := true;
  v_can_override_floor boolean;
  v_lines jsonb := '[]'::jsonb;
  v_line jsonb;
  v_product jsonb;
  v_rule_price_minor bigint;
  v_rule_currency_code text;
  v_local_line_id text;
  v_product_id uuid;
  v_product_unit_id uuid;
  v_quantity_micros bigint;
  v_list_price_minor bigint;
  v_floor_price_minor bigint;
  v_unit_price_minor bigint;
  v_discount_minor bigint;
  v_line_total_minor bigint;
  v_source_code text;
  v_warning_codes jsonb;
  v_blocking_codes jsonb;
  v_manual_intent_count integer;
  v_manual_unit_price_minor bigint;
  v_manual_discount_minor bigint;
  v_manual_discount_basis_points integer;
begin
  if v_actor_id is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from iam.memberships membership
    where membership.tenant_id = p_tenant_id
      and membership.user_id = v_actor_id
  ) then
    raise exception 'tenant access denied';
  end if;

  if not iam.has_permission(p_tenant_id, 'pricing.sales.preview') then
    raise exception 'permission denied: pricing.sales.preview';
  end if;

  if not iam.can_access_store(p_tenant_id, p_store_id, v_actor_id) then
    raise exception 'store access denied';
  end if;

  if v_currency_code <> 'VND' then
    raise exception 'unsupported pricing currency';
  end if;
  if p_context_version < 0 then
    raise exception 'invalid pricing context version';
  end if;
  if p_effective_at is null then
    raise exception 'effective time is required';
  end if;
  if jsonb_typeof(p_lines) <> 'array'
    or jsonb_array_length(p_lines) = 0 then
    raise exception 'pricing lines are required';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(p_lines) line
    group by line ->> 'local_line_id'
    having count(*) > 1
  ) then
    raise exception 'duplicate local line id';
  end if;

  v_can_override_floor := iam.has_permission(
    p_tenant_id,
    'pricing.customer_price_rule.override_floor_price'
  );

  if p_customer_id is not null then
    v_customer := partner._get_customer_snapshot_for_pricing(
      p_tenant_id,
      p_customer_id
    );
    v_customer_valid := coalesce((v_customer ->> 'exists')::boolean, false)
      and coalesce((v_customer ->> 'is_customer')::boolean, false)
      and coalesce(v_customer ->> 'status', '') = 'active';
  end if;

  for v_line in
    select value
    from jsonb_array_elements(p_lines)
  loop
    v_local_line_id := nullif(btrim(v_line ->> 'local_line_id'), '');
    v_warning_codes := '[]'::jsonb;
    v_blocking_codes := '[]'::jsonb;
    v_source_code := 'UNAVAILABLE';
    v_list_price_minor := null;
    v_floor_price_minor := null;
    v_unit_price_minor := 0;
    v_discount_minor := 0;
    v_line_total_minor := 0;

    begin
      v_product_id := (v_line ->> 'product_id')::uuid;
      v_product_unit_id := (v_line ->> 'product_unit_id')::uuid;
      v_quantity_micros := (v_line ->> 'quantity_micros')::bigint;
      v_manual_unit_price_minor := (v_line ->> 'manual_unit_price_minor')::bigint;
      v_manual_discount_minor := (v_line ->> 'manual_discount_minor')::bigint;
      v_manual_discount_basis_points :=
        (v_line ->> 'manual_discount_basis_points')::integer;
    exception when others then
      v_blocking_codes := v_blocking_codes || '"INVALID_LINE"'::jsonb;
      v_product_id := null;
      v_product_unit_id := null;
      v_quantity_micros := 0;
      v_manual_unit_price_minor := null;
      v_manual_discount_minor := null;
      v_manual_discount_basis_points := null;
    end;

    if v_local_line_id is null then
      v_local_line_id := '';
      v_blocking_codes := v_blocking_codes || '"INVALID_LINE_ID"'::jsonb;
    end if;
    if v_quantity_micros <= 0 then
      v_blocking_codes := v_blocking_codes || '"INVALID_QUANTITY"'::jsonb;
    end if;
    if not v_customer_valid then
      v_blocking_codes := v_blocking_codes || '"CUSTOMER_INVALID"'::jsonb;
    end if;

    if v_product_id is not null and v_product_unit_id is not null then
      v_product := catalog._get_product_price_band_snapshot_for_pricing(
        p_tenant_id,
        v_product_id,
        v_product_unit_id
      );

      -- The Catalog snapshot owns product/unit membership, is_ready_to_sell,
      -- currency, and the authoritative store/list price inputs.
      if not coalesce((v_product ->> 'exists')::boolean, false)
        or not coalesce((v_product ->> 'sellable')::boolean, false) then
        v_blocking_codes := v_blocking_codes || '"PRODUCT_NOT_SELLABLE"'::jsonb;
      elsif not coalesce((v_product ->> 'minor_units_valid')::boolean, false) then
        v_blocking_codes := v_blocking_codes || '"PRICE_MINOR_UNITS_INVALID"'::jsonb;
      elsif upper(coalesce(v_product ->> 'currency_code', '')) <> v_currency_code then
        v_blocking_codes := v_blocking_codes || '"CURRENCY_MISMATCH"'::jsonb;
      else
        v_list_price_minor := (v_product ->> 'list_price_minor')::bigint;
        v_floor_price_minor := (v_product ->> 'floor_price_minor')::bigint;
      end if;
    end if;

    v_manual_intent_count :=
      (v_manual_unit_price_minor is not null)::integer
      + (v_manual_discount_minor is not null)::integer
      + (v_manual_discount_basis_points is not null)::integer;

    if v_manual_intent_count > 1
      or coalesce(v_manual_unit_price_minor, 0) < 0
      or coalesce(v_manual_discount_minor, 0) < 0
      or coalesce(v_manual_discount_basis_points, 0) not between 0 and 10000 then
      v_blocking_codes := v_blocking_codes || '"MANUAL_PRICE_INVALID"'::jsonb;
    end if;

    v_rule_price_minor := null;
    v_rule_currency_code := null;
    if p_customer_id is not null
      and v_customer_valid
      and v_product_id is not null
      and v_product_unit_id is not null then
      select rule.rule_price_minor, rule.currency_code
      into v_rule_price_minor, v_rule_currency_code
      from pricing.customer_price_rules rule
      where rule.tenant_id = p_tenant_id
        and rule.customer_id = p_customer_id
        and rule.product_id = v_product_id
        and rule.product_unit_id = v_product_unit_id
        and rule.status = 'active'
        and rule.review_status = 'clear'
        and jsonb_array_length(rule.blocking_codes) = 0
        and rule.effective_from <= (p_effective_at at time zone 'utc')::date
        and (rule.effective_to is null
          or rule.effective_to >= (p_effective_at at time zone 'utc')::date)
      order by rule.effective_from desc, rule.updated_at desc, rule.id desc
      limit 1;
    end if;

    if v_rule_price_minor is not null then
      if upper(v_rule_currency_code) <> v_currency_code then
        v_blocking_codes := v_blocking_codes || '"PRIVATE_RULE_CURRENCY_MISMATCH"'::jsonb;
      else
        v_unit_price_minor := v_rule_price_minor;
        v_source_code := 'CUSTOMER_PRIVATE_RULE';
      end if;
    elsif v_manual_intent_count = 1 and jsonb_array_length(v_blocking_codes) = 0 then
      v_unit_price_minor := case
        when v_manual_unit_price_minor is not null
          then v_manual_unit_price_minor
        when v_manual_discount_minor is not null
          then greatest(v_list_price_minor - v_manual_discount_minor, 0)
        else greatest(
          (v_list_price_minor * (10000 - v_manual_discount_basis_points)) / 10000,
          0
        )
      end;
      v_discount_minor := greatest(v_list_price_minor - v_unit_price_minor, 0);
      v_source_code := 'MANUAL';
      if v_floor_price_minor is not null
        and v_unit_price_minor < v_floor_price_minor then
        -- A3: bo cong quyen; luon cho phep ban duoi san, chi canh bao.
        v_warning_codes := v_warning_codes || '"BELOW_FLOOR"'::jsonb;
      end if;
    elsif v_list_price_minor is not null then
      -- Final precedence source: store/list price.
      v_unit_price_minor := v_list_price_minor;
      v_source_code := 'LIST_PRICE';
    elsif jsonb_array_length(v_blocking_codes) = 0 then
      v_blocking_codes := v_blocking_codes || '"LIST_PRICE_UNAVAILABLE"'::jsonb;
    end if;

    if v_unit_price_minor < 0 or v_discount_minor < 0 then
      v_blocking_codes := v_blocking_codes || '"PRICE_INVALID"'::jsonb;
      v_unit_price_minor := greatest(v_unit_price_minor, 0);
      v_discount_minor := greatest(v_discount_minor, 0);
    end if;
    v_line_total_minor := greatest(
      (v_unit_price_minor * greatest(v_quantity_micros, 0)) / 1000000,
      0
    );

    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'local_line_id', v_local_line_id,
      'applied_unit_price_minor', v_unit_price_minor,
      'discount_minor', v_discount_minor,
      'line_total_minor', v_line_total_minor,
      'source_code', v_source_code,
      'list_price_minor', v_list_price_minor,
      'floor_price_minor', case
        when v_can_override_floor then v_floor_price_minor
        else null
      end,
      'warning_codes', v_warning_codes,
      'blocking_codes', v_blocking_codes
    ));
  end loop;

  return jsonb_build_object(
    'context_version', p_context_version,
    'preview_token', encode(extensions.digest(
      convert_to(jsonb_build_object(
        'tenant_id', p_tenant_id,
        'store_id', p_store_id,
        'customer_id', p_customer_id,
        'currency_code', v_currency_code,
        'context_version', p_context_version,
        'effective_at', p_effective_at,
        'request_lines', p_lines,
        'result_lines', v_lines
      )::text, 'UTF8'),
      'sha256'
    ), 'hex'),
    'currency_code', v_currency_code,
    'lines', v_lines
  );
end;
$$;

create or replace function pricing.evaluate_sales_manual_price(
  p_tenant_id uuid,
  p_store_id uuid,
  p_customer_id uuid,
  p_product_id uuid,
  p_product_unit_id uuid,
  p_quantity_micros bigint,
  p_currency_code text,
  p_context_version integer,
  p_manual_unit_price_minor bigint,
  p_manual_discount_minor bigint,
  p_manual_discount_basis_points integer,
  p_acknowledge_below_floor boolean
)
returns jsonb
language plpgsql
stable
security definer
set search_path = pricing, iam, partner, catalog, pg_temp
as $$
declare
  v_actor_id uuid := auth.uid();
  v_currency_code text := upper(btrim(coalesce(p_currency_code, '')));
  v_product jsonb;
  v_customer jsonb;
  v_list_price_minor bigint;
  v_floor_price_minor bigint;
  v_normalized_price_minor bigint := 0;
  v_intent_count integer;
  v_can_override_floor boolean;
  v_can_view_floor boolean;
  v_allowed boolean := true;
  v_requires_acknowledgement boolean := false;
  v_warning_codes jsonb := '[]'::jsonb;
  v_blocking_code text;
  v_message text;
begin
  if v_actor_id is null then
    raise exception 'not authenticated';
  end if;
  if not exists (
    select 1 from iam.memberships membership
    where membership.tenant_id = p_tenant_id
      and membership.user_id = v_actor_id
  ) then
    raise exception 'tenant access denied';
  end if;
  if not iam.has_permission(p_tenant_id, 'pricing.sales.manual_price.adjust') then
    raise exception 'permission denied: pricing.sales.manual_price.adjust';
  end if;
  if not iam.can_access_store(p_tenant_id, p_store_id, v_actor_id) then
    raise exception 'store access denied';
  end if;

  v_can_override_floor := iam.has_permission(
    p_tenant_id,
    'pricing.customer_price_rule.override_floor_price'
  );
  v_can_view_floor := v_can_override_floor;
  v_intent_count :=
    (p_manual_unit_price_minor is not null)::integer
    + (p_manual_discount_minor is not null)::integer
    + (p_manual_discount_basis_points is not null)::integer;

  if v_currency_code <> 'VND' or p_context_version < 0
    or p_quantity_micros <= 0 or v_intent_count <> 1
    or coalesce(p_manual_unit_price_minor, 0) < 0
    or coalesce(p_manual_discount_minor, 0) < 0
    or coalesce(p_manual_discount_basis_points, 0) not between 0 and 10000 then
    v_allowed := false;
    v_blocking_code := 'MANUAL_PRICE_INVALID';
    v_message := 'Manual price intent is invalid.';
  end if;

  if p_customer_id is not null then
    v_customer := partner._get_customer_snapshot_for_pricing(
      p_tenant_id,
      p_customer_id
    );
    if not coalesce((v_customer ->> 'exists')::boolean, false)
      or not coalesce((v_customer ->> 'is_customer')::boolean, false)
      or coalesce(v_customer ->> 'status', '') <> 'active' then
      v_allowed := false;
      v_blocking_code := 'CUSTOMER_INVALID';
      v_message := 'Customer is not valid for pricing.';
    end if;
  end if;

  v_product := catalog._get_product_price_band_snapshot_for_pricing(
    p_tenant_id,
    p_product_id,
    p_product_unit_id
  );
  if not coalesce((v_product ->> 'exists')::boolean, false)
    or not coalesce((v_product ->> 'sellable')::boolean, false)
    or not coalesce((v_product ->> 'minor_units_valid')::boolean, false)
    or upper(coalesce(v_product ->> 'currency_code', '')) <> v_currency_code then
    v_allowed := false;
    v_blocking_code := 'PRODUCT_PRICE_INVALID';
    v_message := 'Product unit is not sellable in the requested currency.';
  else
    v_list_price_minor := (v_product ->> 'list_price_minor')::bigint;
    v_floor_price_minor := (v_product ->> 'floor_price_minor')::bigint;
  end if;

  if v_allowed then
    v_normalized_price_minor := case
      when p_manual_unit_price_minor is not null
        then p_manual_unit_price_minor
      when p_manual_discount_minor is not null
        then greatest(v_list_price_minor - p_manual_discount_minor, 0)
      else greatest(
        (v_list_price_minor * (10000 - p_manual_discount_basis_points)) / 10000,
        0
      )
    end;

    if v_floor_price_minor is not null
      and v_normalized_price_minor < v_floor_price_minor then
      -- A3: bo cong quyen; ai cung ban duoi san duoc, nhung phai xac nhan (canh bao).
      if not coalesce(p_acknowledge_below_floor, false) then
        v_requires_acknowledgement := true;
        v_warning_codes := v_warning_codes || '"BELOW_FLOOR"'::jsonb;
        v_message := 'Below-floor pricing requires acknowledgement.';
      else
        v_warning_codes := v_warning_codes || '"BELOW_FLOOR"'::jsonb;
      end if;
    end if;
  end if;

  return jsonb_build_object(
    'allowed', v_allowed,
    'requires_acknowledgement', v_requires_acknowledgement,
    'normalized_unit_price_minor', greatest(v_normalized_price_minor, 0),
    'floor_price_minor', case when v_can_view_floor then v_floor_price_minor else null end,
    'can_view_floor', v_can_view_floor,
    'warning_codes', v_warning_codes,
    'blocking_code', v_blocking_code,
    'message', v_message
  );
end;
$$;

revoke all on function pricing.preview_sales_working_state_pricing(
  uuid, uuid, uuid, text, integer, timestamptz, jsonb
) from public, anon, authenticated, service_role;
grant execute on function pricing.preview_sales_working_state_pricing(
  uuid, uuid, uuid, text, integer, timestamptz, jsonb
) to authenticated, service_role;

revoke all on function pricing.evaluate_sales_manual_price(
  uuid, uuid, uuid, uuid, uuid, bigint, text, integer,
  bigint, bigint, integer, boolean
) from public, anon, authenticated, service_role;
grant execute on function pricing.evaluate_sales_manual_price(
  uuid, uuid, uuid, uuid, uuid, bigint, text, integer,
  bigint, bigint, integer, boolean
) to authenticated, service_role;
